import sys, json
from typing import List

class Solution:
    def connectTwoGroups(self, cost: List[List[int]]) -> int:
        n = len(cost[0])
        full = 1 << n
        INF = 10**18
        dp = [INF] * full
        dp[0] = 0

        for row in cost:
            cur = [INF] * full
            for mask in range(full):
                if dp[mask] != INF:
                    cur[mask] = dp[mask]
            # Choose at least one connection from this row, then allow
            # additional connections to cover more right-group points.
            first = [INF] * full
            for mask in range(full):
                if dp[mask] == INF:
                    continue
                for j in range(n):
                    nm = mask | (1 << j)
                    first[nm] = min(first[nm], dp[mask] + row[j])
            cur = first
            for j in range(n):
                bit = 1 << j
                for mask in range(full):
                    if cur[mask] != INF:
                        nm = mask | bit
                        cur[nm] = min(cur[nm], cur[mask] + row[j])
            dp = cur

        return dp[full - 1]

