#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

int connectTwoGroups(int** cost, int costSize, int* costColSize) {
    int n = costColSize[0], full = 1 << n, INF = 1000000000;
    int* dp = (int*)malloc(full * sizeof(int));
    int* cur = (int*)malloc(full * sizeof(int));

    for (int mask = 0; mask < full; ++mask) dp[mask] = INF;
    dp[0] = 0;

    for (int i = 0; i < costSize; ++i) {
        for (int mask = 0; mask < full; ++mask) cur[mask] = INF;
        for (int mask = 0; mask < full; ++mask) {
            if (dp[mask] == INF) continue;
            for (int j = 0; j < n; ++j) {
                int nm = mask | (1 << j);
                int v = dp[mask] + cost[i][j];
                if (v < cur[nm]) cur[nm] = v;
            }
        }
        for (int j = 0; j < n; ++j) {
            int bit = 1 << j;
            for (int mask = 0; mask < full; ++mask) {
                if (cur[mask] == INF) continue;
                int nm = mask | bit;
                int v = cur[mask] + cost[i][j];
                if (v < cur[nm]) cur[nm] = v;
            }
        }
        int* tmp = dp; dp = cur; cur = tmp;
    }

    int ans = dp[full - 1];
    free(dp); free(cur);
    return ans;
}

static void skip(const char* s, int* p) {
    while (s[*p] && (s[*p] == ' ' || s[*p] == ',' || s[*p] == '\n' || s[*p] == '\r')) (*p)++;
}
static int parseInt(const char* s, int* p) {
    skip(s, p);
    int sign = 1, x = 0;
    if (s[*p] == '-') { sign = -1; (*p)++; }
    while (isdigit((unsigned char)s[*p])) { x = x * 10 + s[*p] - '0'; (*p)++; }
    return sign * x;
}
static void parseMatrix(const char* s, int*** out, int* rows, int** cols) {
    int p = 0, r = 0;
    while (s[p] && s[p] != '[') p++;
    p++;
    int** mat = (int**)malloc(12 * sizeof(int*));
    int* cs = (int*)malloc(12 * sizeof(int));
    while (s[p] && s[p] != ']') {
        skip(s, &p);
        if (s[p] != '[') { p++; continue; }
        p++;
        int* row = (int*)malloc(12 * sizeof(int));
        int c = 0;
        while (s[p] && s[p] != ']') {
            row[c++] = parseInt(s, &p);
            skip(s, &p);
        }
        if (s[p] == ']') p++;
        mat[r] = row;
        cs[r] = c;
        r++;
        skip(s, &p);
    }
    *out = mat; *rows = r; *cols = cs;
}

int main(void) {
    char line[200000];
    if (!fgets(line, sizeof(line), stdin)) return 0;
    int** cost; int rows; int* cols;
    parseMatrix(line, &cost, &rows, &cols);
    int result = connectTwoGroups(cost, rows, cols);
    printf("%d\n", result);
    for (int i = 0; i < rows; ++i) free(cost[i]);
    free(cost); free(cols);
    return 0;
}

