#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int connectTwoGroups(vector<vector<int>>& cost) {
        int n = cost[0].size();
        int full = 1 << n;
        const int INF = 1e9;
        vector<int> dp(full, INF);
        dp[0] = 0;

        for (const auto& row : cost) {
            vector<int> cur(full, INF);
            for (int mask = 0; mask < full; ++mask) {
                if (dp[mask] == INF) continue;
                for (int j = 0; j < n; ++j) {
                    int nm = mask | (1 << j);
                    cur[nm] = min(cur[nm], dp[mask] + row[j]);
                }
            }
            for (int j = 0; j < n; ++j) {
                int bit = 1 << j;
                for (int mask = 0; mask < full; ++mask) {
                    if (cur[mask] == INF) continue;
                    int nm = mask | bit;
                    cur[nm] = min(cur[nm], cur[mask] + row[j]);
                }
            }
            dp.swap(cur);
        }
        return dp[full - 1];
    }
};

static void skip(const string& s, size_t& p) {
    while (p < s.size() && (s[p] == ' ' || s[p] == ',' || s[p] == '\n' || s[p] == '\r')) ++p;
}
static vector<int> parseRow(const string& s, size_t& p) {
    vector<int> row;
    while (p < s.size() && s[p] != '[') ++p;
    ++p;
    while (p < s.size() && s[p] != ']') {
        skip(s, p);
        if (p >= s.size() || s[p] == ']') break;
        int sign = 1;
        if (s[p] == '-') { sign = -1; ++p; }
        int x = 0;
        while (p < s.size() && isdigit((unsigned char)s[p])) x = x * 10 + (s[p++] - '0');
        row.push_back(sign * x);
        skip(s, p);
    }
    if (p < s.size() && s[p] == ']') ++p;
    return row;
}
static vector<vector<int>> parseMatrix(const string& s) {
    vector<vector<int>> m;
    size_t p = 0;
    while (p < s.size() && s[p] != '[') ++p;
    ++p;
    while (p < s.size()) {
        skip(s, p);
        if (p >= s.size() || s[p] == ']') break;
        if (s[p] == '[') m.push_back(parseRow(s, p));
        else ++p;
    }
    return m;
}

int main() {
    string line;
    getline(cin, line);
    vector<vector<int>> cost = parseMatrix(line);
    cout << Solution().connectTwoGroups(cost) << '\n';
    return 0;
}

