import java.io.*;
import java.util.*;

class Solution {
    public int connectTwoGroups(List<List<Integer>> cost) {
        int n = cost.get(0).size();
        int full = 1 << n;
        int INF = 1_000_000_000;
        int[] dp = new int[full];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (List<Integer> row : cost) {
            int[] cur = new int[full];
            Arrays.fill(cur, INF);
            for (int mask = 0; mask < full; mask++) {
                if (dp[mask] == INF) continue;
                for (int j = 0; j < n; j++) {
                    int nm = mask | (1 << j);
                    cur[nm] = Math.min(cur[nm], dp[mask] + row.get(j));
                }
            }
            for (int j = 0; j < n; j++) {
                int bit = 1 << j;
                for (int mask = 0; mask < full; mask++) {
                    if (cur[mask] == INF) continue;
                    int nm = mask | bit;
                    cur[nm] = Math.min(cur[nm], cur[mask] + row.get(j));
                }
            }
            dp = cur;
        }
        return dp[full - 1];
    }
}

public class Main {
    static List<List<Integer>> parse(String s) {
        List<List<Integer>> result = new ArrayList<>();
        int i = 0;
        while (i < s.length() && s.charAt(i) != '[') i++;
        i++;
        while (i < s.length()) {
            while (i < s.length() && (s.charAt(i) == ' ' || s.charAt(i) == ',' || s.charAt(i) == '\n')) i++;
            if (i < s.length() && s.charAt(i) == '[') {
                i++;
                List<Integer> row = new ArrayList<>();
                StringBuilder num = new StringBuilder();
                while (i < s.length() && s.charAt(i) != ']') {
                    char c = s.charAt(i++);
                    if (Character.isDigit(c)) num.append(c);
                    else if (c == ',' || c == ' ') {
                        if (num.length() > 0) { row.add(Integer.parseInt(num.toString())); num.setLength(0); }
                    }
                }
                if (num.length() > 0) row.add(Integer.parseInt(num.toString()));
                if (i < s.length()) i++;
                result.add(row);
            } else break;
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        List<List<Integer>> cost = parse(line);
        System.out.println(new Solution().connectTwoGroups(cost));
    }
}

